function write(rel, text) { changed[rel] = text; }
function applyEdit(edit) {
  const source = read(edit.file);
  if (edit.mode === 'range') {
    const start = source.indexOf(edit.start);
    if (start < 0 || source.indexOf(edit.start, start + edit.start.length) >= 0) {
      throw new Error(edit.file + '／' + edit.label + '：起始標記不存在或不唯一；已中止，沒有寫入任何檔案。');
    }
    const end = source.indexOf(edit.end, start + edit.start.length);
    if (end < 0) throw new Error(edit.file + '／' + edit.label + '：找不到結束標記；已中止，沒有寫入任何檔案。');
    write(edit.file, source.slice(0, start) + edit.new + source.slice(end));
  } else {
    const count = source.split(edit.old).length - 1;
    if (count !== 1) throw new Error(edit.file + '／' + edit.label + '：預期匹配 1 處，實際 ' + count + ' 處；已中止，沒有寫入任何檔案。');
    write(edit.file, source.replace(edit.old, edit.new));
  }
  labels.push(edit.file + '：' + edit.label);
}
